{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.slikk_inventory as WITH inv_sent AS ( SELECT CASE WHEN upper(trim(factsss.sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-05-SHIRT-L\' THEN \'4MSN1310-05-L\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-05-SHIRT-XL\' THEN \'4MSN1310-05-XL\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-05-SHIRT-XXL\' THEN \'4MSN1310-05-XXL\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-02-SHIRT-S\' THEN \'4MSN1310-02-S\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-02-SHIRT-M\' THEN \'4MSN1310-02-M\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-02-SHIRT-L\' THEN \'4MSN1310-02-L\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-02-SHIRT-XL\' THEN \'4MSN1310-02-XL\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-02-SHIRT-XXL\' THEN \'4MSN1310-02-XXL\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-08-SHIRT-S\' THEN \'4MSN1310-08-S\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-08-SHIRT-M\' THEN \'4MSN1310-08-M\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-08-SHIRT-L\' THEN \'4MSN1310-08-L\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-08-SHIRT-XL\' THEN \'4MSN1310-08-XL\' WHEN upper(trim(factsss.sku)) = \'4MSN1310-08-SHIRT-XXL\' THEN \'4MSN1310-08-XXL\' ELSE upper(trim(factsss.sku)) END AS sku, COALESCE( TO_DATE(sheet.SLOT_DATE, \'DD/MM/YYYY\'), TO_DATE(sheet.ORDER_DATE, \'DD/MM/YYYY\'), factsss.ORDER_DATE ) AS inward_date, SUM(factsss.SUBORDER_QUANTITY) AS qty_sent FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate AS factsss LEFT JOIN snitch_db.maplemonk.gs_mpforwards_sheet1 AS sheet ON factsss.order_id = sheet.SO_NUMBER AND sheet.MARKETPLACE = \'Slikk\' WHERE (factsss.MARKETPLACE_MAPPED = \'SLIKK\' OR factsss.MARKETPLACE_MAPPED = \'Slikk\') AND factsss.SALE_ORDER_ITEM_STATUS NOT IN (\'CANCELLED\', \'UNFULFILLABLE\') GROUP BY 1, 2 ), min_dates AS ( SELECT sku, MIN(inward_date) AS first_inward_date FROM inv_sent GROUP BY 1 ), date_expanded AS ( SELECT m.sku, DATEADD(DAY, s.seq, m.first_inward_date) AS generated_date FROM min_dates m, LATERAL ( SELECT SEQ4() AS seq FROM TABLE(GENERATOR(ROWCOUNT => 10000)) ) s WHERE DATEADD(DAY, s.seq, m.first_inward_date) <= CURRENT_DATE() + 1 ), main_data AS ( SELECT sku, generated_date AS date FROM date_expanded ), sales AS ( SELECT sku, order_date, SUM(total_quantity) AS sales_qty, SUM(return_quantity) AS ret_qty FROM snitch_db.maplemonk.slikk_fact_item GROUP BY 1, 2 ), outward AS ( SELECT CASE WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-S\' THEN \'4MSN1310-05-S\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-M\' THEN \'4MSN1310-05-M\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-L\' THEN \'4MSN1310-05-L\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XL\' THEN \'4MSN1310-05-XL\' WHEN upper(trim(sku)) = \'4MSN1310-05-SHIRT-XXL\' THEN \'4MSN1310-05-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-S\' THEN \'4MSN1310-02-S\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-M\' THEN \'4MSN1310-02-M\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-L\' THEN \'4MSN1310-02-L\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XL\' THEN \'4MSN1310-02-XL\' WHEN upper(trim(sku)) = \'4MSN1310-02-SHIRT-XXL\' THEN \'4MSN1310-02-XXL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-S\' THEN \'4MSN1310-08-S\' WHEN upper(trim(sku)) = \'4MSN1to1310-08-SHIRT-M\' THEN \'4MSN1310-08-M\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-L\' THEN \'4MSN1310-08-L\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XL\' THEN \'4MSN1310-08-XL\' WHEN upper(trim(sku)) = \'4MSN1310-08-SHIRT-XXL\' THEN \'4MSN1310-08-XXL\' ELSE upper(trim(sku)) END AS sku, TO_DATE(TRIM(t._AB_ADDITIONAL_PROPERTIES:\"Date \"), \'DD-MM-YYYY\') AS outward_date, SUM(TRIM(t._AB_ADDITIONAL_PROPERTIES:\"Pullback Inv \")::INT) AS Pullback_Inventory FROM snitch_db.maplemonk.S3_SLIKK_PULLBACK AS t GROUP BY 1, 2 ), base_data AS ( Select sku, Date, first_inward_date, sum(qty_sent) as qty_sent, sum(sales_qty) as sales_qty, sum(ret_qty) as ret_qty, sum(Pullback_Inventory) as Pullback_Inventory From ( SELECT COALESCE(a.sku, c.sku) AS sku, COALESCE(a.date,e.first_inward_date) as Date , COALESCE(b.qty_sent, 0) AS qty_sent, COALESCE(c.sales_qty, 0) AS sales_qty, COALESCE(c.ret_qty, 0) AS ret_qty, COALESCE(d.Pullback_Inventory, 0) AS pullback_inventory, e.first_inward_date FROM main_data a LEFT JOIN inv_sent b ON a.date = b.inward_date AND a.sku = b.sku FULL OUTER JOIN sales c ON a.date = c.order_date AND a.sku = c.sku LEFT JOIN outward d ON a.date = d.outward_date AND a.sku = d.sku LEFT JOIN min_dates e ON COALESCE(a.sku, c.sku) = e.sku ) group by 1,2,3 ), ordered_data AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, pullback_inventory, first_inward_date FROM base_data WHERE sku IS NOT NULL AND date IS NOT NULL ), initial_rows AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, pullback_inventory, first_inward_date, 0 AS closing_inventory, qty_sent AS opening_inventory, qty_sent - sales_qty + ret_qty - pullback_inventory AS closing_inventory_new FROM ordered_data WHERE (sku, date) IN ( SELECT sku, MIN(date) FROM ordered_data GROUP BY sku ) ), recursive_inventory AS ( SELECT * FROM initial_rows UNION ALL SELECT curr.sku, curr.date, curr.qty_sent, curr.sales_qty, curr.ret_qty, curr.pullback_inventory, curr.first_inward_date, prev.closing_inventory_new AS closing_inventory, prev.closing_inventory_new + curr.qty_sent AS opening_inventory, prev.closing_inventory_new + curr.qty_sent - curr.sales_qty + curr.ret_qty - curr.pullback_inventory AS closing_inventory_new FROM recursive_inventory prev JOIN ordered_data curr ON curr.sku = prev.sku AND curr.date = DATEADD(DAY, 1, prev.date) ), with_sku_group AS ( SELECT *, REGEXP_REPLACE(sku, \'-[^-]*$\', \'\') AS sku_group, SPLIT_PART(sku, \'-\', ARRAY_SIZE(SPLIT(sku, \'-\'))) AS size FROM recursive_inventory ), latest_metafields AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) AS rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) SELECT w.sku, w.sku_group, w.size, w.date, w.qty_sent, w.sales_qty, w.ret_qty, w.pullback_inventory, w.first_inward_date, w.opening_inventory, w.closing_inventory_new AS closing_inventory, m.category, m.title, m.material_new, m.print_design, m.fit, m.sleeve_type, m.collar_new FROM with_sku_group w LEFT JOIN latest_metafields m ON w.sku_group = m.sku_group ORDER BY w.sku, w.date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

